{endregion}
(* Hardware Inputs "Common" Equipment Module *)
{region "Common"}

{endregion}

(* Hardware Outputs "BovHfd" Equipment Module *)
{region "BovHfd"}

{endregion}
(* Hardware Outputs "BenHfd" Equipment Module *)
{region "BenHfd"}

{endregion}
(* Hardware Outputs "Common" Equipment Module *)
{region "Common"}
{endregion}

//AutoRestart logic
ChargeEdge(CLK:=Operating.OperatingFlow.State.Charge);
IF ChargeEdge.Q THEN
	IF Operating.Batt.State.BelowLowSocShutdown THEN
		ChargeBecauseLow := TRUE;
	ELSE
		ChargebecauseLow := FALSE;
	END_IF
END_IF

IF ChargeBecauseLow AND ChargeCounter = 0 THEN
	AutoRestart := TRUE;
ELSE
	AutoRestart := FALSE;
END_IF

IF ChargeBecauseLow AND AutoRestart AND Operating.OperatingFlow.State.Charge AND Operating.Batt.State.AboveLowSocCleared THEN
	ChargeCounter := 1;
END_IF

IF Operating.Batt.State.Soc >= 90.0 THEN
	ChargeCounter := 0;
END_IF

// transities
//1. from startup
// delayed start
WaitForStartupTimer(IN:=Operating.OperatingFlow.State.Startup AND Operating.Rfid.State.Sv , PT:=T#210S); 

Operating.OperatingFlow.Trans.StartupToActive := WaitForStartupTimer.Q AND Operating.PushBtn.State.ShortEdge AND Operating.Batt.State.AboveLowSocShutdown;

Operating.OperatingFlow.Trans.StartupToCharge := WaitForStartupTimer.Q AND Operating.PushBtn.State.ShortEdge AND Operating.Batt.State.BelowLowSocShutdown;

//Operating.OperatingFlow.Trans.StartupToError := Operating.Error.ErrorActive;

//2. from active
//Operating.OperatingFlow.Trans.ActiveToStartup := FALSE;
(*
Operating.OperatingFlow.Trans.ActiveToCharge := Operating.PushBtn.State.ShortEdge OR (Operating.Batt.State.BelowLowSocShutdown AND NOT Operating.Batt.Alarm.SocInvalid)
OR (Operating.StateInfo.BMS1DischargingProhibited OR Operating.StateInfo.BMS2DischargingProhibited OR Operating.StateInfo.BMS3DischargingProhibited)OR (Operating.StateInfo.CellVoltage.Minimum < 3.1 AND Operating.StateInfo.CellVoltage.Minimum > 0.0)
OR NOT Operating.RfidClosed.State.Sv ;
*)
Operating.OperatingFlow.Trans.ActiveToCharge := Operating.PushBtn.State.ShortEdge OR Operating.Batt.State.BelowLowSocShutdown
OR Operating.Batt.Alarm.DischProhib OR Operating.Batt.Alarm.CellVoltLow OR NOT Operating.Rfid.State.Sv;

//Operating.OperatingFlow.Trans.ActiveToError := Operating.Error.ErrorActive;

//3. from charge
//Operating.OperatingFlow.Trans.ChargeToStartup := FALSE;

Operating.OperatingFlow.Trans.ChargeToActive := ( (Operating.Batt.State.AboveLowSocCleared AND (Operating.PushBtn.State.ShortEdge OR AutoRestart)) 
OR Operating.Batt.State.Full)
AND Operating.Rfid.State.Sv;

//Operating.OperatingFlow.Trans.ChargeToError := Operating.Error.ErrorActive;

// actions
//LEDs
Operating.Rgb.Cmd.Off := (Operating.OperatingFlow.State.Startup AND NOT(WaitForStartupTimer.Q));// OR ShutDownComplete;
Operating.Rgb.Cmd.On := Operating.OperatingFlow.State.Active OR Operating.OperatingFlow.State.Error;
Operating.Rgb.Cmd.BlinkSlow := Operating.OperatingFlow.State.Charge OR (Operating.OperatingFlow.State.Startup AND WaitForStartupTimer.Q);
Operating.Rgb.Cmd.Blink := Operating.OperatingFlow.State.Softreset;
IF (Operating.OperatingFlow.State.Active OR Operating.OperatingFlow.State.Charge OR Operating.OperatingFlow.State.Startup) AND Operating.Rfid.State.Sv THEN
	IF Operating.Batt.State.AboveLowSocCleared THEN
		Operating.Rgb.Cmd.Color := 'Green';
	ELSIF Operating.Batt.State.BelowLowSocPreAlarm THEN
		Operating.Rgb.Cmd.Color := 'Orange';
	END_IF
END_IF
IF Operating.OperatingFlow.State.Error THEN
	Operating.Rgb.Cmd.Color := 'Red';
END_IF
IF Operating.OperatingFlow.State.Softreset THEN
	Operating.Rgb.Cmd.Color := 'Orange';
END_IF
(*
IF ShutdownComplete THEN
	Operating.Rgb.Cmd.Color := 'None';
END_IF
*)
//AC-out
Operating.AC_OUT.Cmd.Close := Operating.OperatingFlow.State.Active;
Operating.AC_OUT.Cmd.Open := Operating.OperatingFlow.State.Charge OR Operating.OperatingFlow.State.Error OR Operating.OperatingFlow.State.Startup;

//Buzzer
IF Operating.OperatingFlow.State.Active AND Operating.Batt.State.BelowLowSocPreAlarm THEN
	Operating.Buzzer.Cmd.On := TRUE;
ELSIF Operating.Batt.State.AboveLowSocCleared OR NOT Operating.OperatingFlow.State.Active THEN
	Operating.Buzzer.Cmd.On := FALSE;
END_IF;

//Startup
ScreenTimer(IN := Operating.OperatingFlow.State.Startup, PT := T#30S);
Operating.Batt.Cmd.Start := Operating.Rfid.State.Sv AND Operating.OperatingFlow.State.Startup AND ScreenTimer.Q;

//Shutdown
IF Operating.Rfid.State.Sv THEN
	WentOn := TRUE;
END_IF
NoGridTON(IN:=(Operating.OperatingFlow.State.Startup OR Operating.OperatingFlow.State.Charge) AND Operating.OperatingFlow.NoGrid, PT:=T#1H);
Operating.Batt.Cmd.Stop := (NOT Operating.Rfid.State.Sv AND WentOn) OR NoGridTon.Q OR Operating.OperatingFlow.Trans.ResetToSoftreset;
ShutDownTimer(IN := Operating.Batt.Cmd.Stop, PT:=T#15S);
IF ShutDowntimer.Q THEN
	IF NOT Operating.OperatingFlow.Trans.ResetToSoftreset THEN
		ShutdownComplete := TRUE;
	END_IF
	WentOn := False;
END_IF
